window.products.push({"id":79437,"name":"Frigidaire 24\" White Built-In Dishwasher","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/419-eQ3E5oL._AC_SL1200_.jpg","description":"This 24\" Built-in Dishwasher from Frigidaire features 3 wash cycles with up to 14 place settings in one cycle. The dishwasher also features delay start, cycle status indicators, a filtration system, a heated drying system and is Energy Star certified.","images":["https://m.media-amazon.com/images/I/419-eQ3E5oL._AC_SL1200_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"FRIGIDAIRE","source_asin":"B07GDTWRBZ","category_path":"Home & Appliances"},"sku":"BM-79437","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B07GDTWRBZ","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Appliances.jsonl","source_asin":"B07GDTWRBZ","price_pending":true,"merchant_ready":false});
